from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Ls(EmssimCommand):
    def __init__(self, method="ls", timeout=60, rpc_connection_name='localRPC'):
        super(Ls, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Ls, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "states"):
                self._ret['object_table'] = self.parse_table_with_unique_key_to_dictionary(data['table'], "DEVICE")
        elif ("status" in data):
            self._ret["status"] = data["status"]
